        overlayManager.add(piecesOfEightOverlay);
        overlayManager.add(brewStatusOverlay);
        overlayManager.add(monkeyDialogueOverlay);
        beginBootstrapScan();
        clientThread.invokeLater(this::updatePiecesOfEight);
