package com.tbhelper;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.Shape;
import java.awt.Stroke;
import java.awt.image.BufferedImage;
import java.util.LinkedHashMap;
import java.util.Map;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.widgets.Widget;
import net.runelite.api.widgets.WidgetItem;
import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.overlay.WidgetItemOverlay;
import net.runelite.client.util.ImageUtil;

/** Draws the same category colours over matching Trouble Brewing inventory items. */
public class TroubleBrewingInventoryOverlay extends WidgetItemOverlay
{
    private static final long FLASH_INTERVAL_MS = 500L;
    private static final float SUPPLY_BADGE_FONT_SIZE = 13F;
    private static final int SUPPLY_BADGE_PADDING_X = 3;
    private static final Color SUPPLY_BADGE_BACKGROUND = new Color(0, 0, 0, 190);
    private static final Color SUPPLY_READY_COLOR = new Color(85, 220, 100);
    private static final Color SUPPLY_PARTIAL_COLOR = new Color(255, 145, 35);
    private static final Color SUPPLY_EMPTY_COLOR = new Color(235, 80, 80);
    private static final int ITEM_OUTLINE_CACHE_SIZE = 128;
    private final Client client;
    private final ItemManager itemManager;
    private final TroubleBrewingHighlighterPlugin plugin;
    private final TroubleBrewingHighlighterConfig config;
    private final Map<ItemOutlineKey, BufferedImage> itemOutlineCache =
        new LinkedHashMap<ItemOutlineKey, BufferedImage>(ITEM_OUTLINE_CACHE_SIZE, 0.75F, true)
        {
            @Override
            protected boolean removeEldestEntry(Map.Entry<ItemOutlineKey, BufferedImage> eldest)
            {
                return size() > ITEM_OUTLINE_CACHE_SIZE;
            }
        };

    @Inject
    private TroubleBrewingInventoryOverlay(
        Client client,
        ItemManager itemManager,
        TroubleBrewingHighlighterPlugin plugin,
        TroubleBrewingHighlighterConfig config)
    {
        this.client = client;
        this.itemManager = itemManager;
        this.plugin = plugin;
        this.config = config;
        showOnInventory();
        showOnInterfaces(InterfaceID.BREW_TOOLS);
    }

    @Override
    public Dimension render(Graphics2D graphics)
    {
        Shape oldClip = graphics.getClip();
        Dimension dimension = super.render(graphics);
        graphics.setClip(oldClip);

        if (!plugin.isTroubleBrewingSceneLoaded())
        {
            return dimension;
        }

        renderToolWidget(graphics, InterfaceID.BrewTools.BUCKET_MODEL1, ResourceType.WATER);
        renderToolWidget(graphics, InterfaceID.BrewTools.TINDERBOX_MODEL1, ResourceType.BOILER_FUEL);
        renderToolWidget(graphics, InterfaceID.BrewTools.AXE_MODEL1, ResourceType.BARK);
        renderToolWidget(graphics, InterfaceID.BrewTools.KNIFE_MODEL1, ResourceType.BARK);
        renderToolWidget(graphics, InterfaceID.BrewTools.BOWL_MODEL1, ResourceType.FLOWERS);
        renderToolWidget(graphics, InterfaceID.BrewTools.MEAT_MODEL1, ResourceType.BAIT);
        renderToolWidget(graphics, InterfaceID.BrewTools.BAMBOO_MODEL1, ResourceType.PIPE_REPAIR);
        renderToolWidget(graphics, InterfaceID.BrewTools.BRIDGE_MODEL1, ResourceType.DAMAGE_REPAIR);
        renderToolWidget(graphics, InterfaceID.BrewTools.PATCH_MODEL1, ResourceType.LUMBER_REPAIR);
        return dimension;
    }

    @Override
    public void renderItemOverlay(
        Graphics2D graphics,
        int itemId,
        WidgetItem widgetItem)
    {
        // Generic IDs such as buckets and axes should only be coloured while
        // the Trouble Brewing scene itself is loaded.
        if (!plugin.isTroubleBrewingSceneLoaded())
        {
            return;
        }

        InventoryHighlightStyle highlightStyle = config.inventoryHighlightStyle();
        if (highlightStyle == InventoryHighlightStyle.OFF)
        {
            return;
        }

        ResourceType resourceType = ObjectDatabase.getItem(itemId);
        if ((itemId == ItemID.LOGS && !plugin.needsBoilerLogs())
            || (itemId == ItemID.TINDERBOX && !plugin.needsBoilerLighting()))
        {
            return;
        }

        boolean emergencyWater = itemId == ItemID.BUCKET_WATER
            && plugin.hasLocalTeamFire()
            && config.showDamageRepair();
        if (resourceType == null || (!emergencyWater && !isCategoryEnabled(resourceType)))
        {
            return;
        }

        Rectangle bounds = widgetItem.getCanvasBounds();
        if (bounds == null)
        {
            return;
        }

        if (!isFlashing(resourceType, emergencyWater) || isFlashOn())
        {
            Color colour = emergencyWater
                ? config.damageRepairColour()
                : colourFor(resourceType);
            if (highlightStyle == InventoryHighlightStyle.ITEM_OUTLINE)
            {
                renderItemOutline(
                    graphics,
                    bounds,
                    itemId,
                    widgetItem.getQuantity(),
                    colour
                );
            }
            else
            {
                renderBounds(graphics, bounds, colour);
            }
        }
        renderSupplyBadge(graphics, bounds, itemId, resourceType);
    }

    private void renderSupplyBadge(
        Graphics2D graphics,
        Rectangle bounds,
        int itemId,
        ResourceType resourceType)
    {
        if (!plugin.isTroubleBrewingMatchActive())
        {
            return;
        }

        boolean waterBucket = isWaterBucket(itemId);
        boolean showBadge = shouldShowSupplyBadge(
            config.afkerMode(),
            waterBucket,
            config.showWaterBucketCount(),
            config.showStationAmounts()
        );
        if (!showBadge)
        {
            return;
        }

        int current;
        int perRum;
        if (itemId == ItemID.BREW_MONKEY)
        {
            // Preserve the plain monkey's route colour, but show the supply it
            // is used to collect rather than the coloured-water total.
            current = plugin.getTeamBitternuts();
            perRum = 1;
        }
        else
        {
            switch (resourceType)
            {
                case WATER:
                    current = plugin.getTeamBuckets();
                    perRum = 5;
                    break;
                case COLOURED_WATER:
                case FLOWERS:
                    current = plugin.getTeamColouredWater();
                    perRum = 3;
                    break;
                case BARK:
                    if (itemId == ItemID.BRONZE_AXE || itemId == ItemID.KNIFE)
                    {
                        return;
                    }
                    current = plugin.getTeamBark();
                    perRum = 1;
                    break;
                case PROCESSED_BARK:
                    current = plugin.getTeamBark();
                    perRum = 1;
                    break;
                case BAIT:
                case GRUBS:
                    current = plugin.getTeamSweetgrubs();
                    perRum = 1;
                    break;
                case BITTERNUTS:
                case BITTERNUTS_FINAL:
                    current = plugin.getTeamBitternuts();
                    perRum = 1;
                    break;
                default:
                    return;
            }
        }

        int required = plugin.getPossibleRumsLeft() * perRum;
        String text = current + "/" + required;
        Font oldFont = graphics.getFont();
        Color oldColor = graphics.getColor();
        graphics.setFont(oldFont.deriveFont(Font.BOLD, SUPPLY_BADGE_FONT_SIZE));
        int textWidth = graphics.getFontMetrics().stringWidth(text);
        int textX = bounds.x + ((bounds.width - textWidth) / 2);
        int textY = bounds.y + graphics.getFontMetrics().getAscent() + 1;
        int backgroundX = textX - SUPPLY_BADGE_PADDING_X;
        int backgroundWidth = textWidth + (SUPPLY_BADGE_PADDING_X * 2);
        int backgroundHeight = graphics.getFontMetrics().getHeight() + 1;
        graphics.setColor(SUPPLY_BADGE_BACKGROUND);
        graphics.fillRoundRect(
            backgroundX,
            bounds.y,
            backgroundWidth,
            backgroundHeight,
            4,
            4
        );
        graphics.setColor(Color.BLACK);
        graphics.drawString(text, textX - 1, textY);
        graphics.drawString(text, textX + 1, textY);
        graphics.drawString(text, textX, textY - 1);
        graphics.drawString(text, textX, textY + 1);
        graphics.setColor(supplyColour(current, required));
        graphics.drawString(text, textX, textY);
        graphics.setFont(oldFont);
        graphics.setColor(oldColor);
    }

    private static Color supplyColour(int current, int required)
    {
        if (required <= 0 || current >= required)
        {
            return SUPPLY_READY_COLOR;
        }
        return current <= 0 ? SUPPLY_EMPTY_COLOR : SUPPLY_PARTIAL_COLOR;
    }

    private void renderToolWidget(Graphics2D graphics, int componentId, ResourceType resourceType)
    {
        if (!isEnabled(resourceType, false))
        {
            return;
        }

        Widget widget = client.getWidget(componentId);
        if (widget == null || widget.isHidden())
        {
            return;
        }

        Rectangle bounds = widget.getBounds();
        if (bounds != null)
        {
            renderBounds(graphics, bounds, colourFor(resourceType));
        }
    }

    private void renderBounds(Graphics2D graphics, Rectangle bounds, Color colour)
    {
        Stroke oldStroke = graphics.getStroke();
        Color oldColor = graphics.getColor();

        graphics.setStroke(new BasicStroke((float) config.outlineWidth()));
        graphics.setColor(withAlpha(colour, config.fillOpacity()));
        graphics.fill(bounds);
        graphics.setColor(colour);
        graphics.draw(bounds);

        graphics.setStroke(oldStroke);
        graphics.setColor(oldColor);
    }

    private void renderItemOutline(
        Graphics2D graphics,
        Rectangle bounds,
        int itemId,
        int quantity,
        Color colour)
    {
        int size = Math.max(1, Math.min(config.inventoryOutlineSize(), 9));
        ItemOutlineKey key = new ItemOutlineKey(itemId, quantity, colour.getRGB(), size);
        BufferedImage outline = itemOutlineCache.get(key);
        if (outline == null)
        {
            outline = itemManager.getItemOutline(itemId, quantity, colour);
            if (outline == null)
            {
                return;
            }

            int additionalFullLayers = (size - 1) / 4;
            for (int layer = 0; layer < additionalFullLayers; layer++)
            {
                outline = ImageUtil.outlineImage(outline, colour, true);
            }

            int partialLayer = (size - 1) % 4;
            if (partialLayer > 0)
            {
                Color partialColour = new Color(
                    colour.getRed(),
                    colour.getGreen(),
                    colour.getBlue(),
                    partialLayer * 64
                );
                outline = ImageUtil.outlineImage(outline, partialColour, true);
            }
            itemOutlineCache.put(key, outline);
        }

        graphics.drawImage(outline, bounds.x, bounds.y, null);
    }

    private static boolean isWaterBucket(int itemId)
    {
        return itemId == ItemID.BUCKET_EMPTY
            || itemId == ItemID.BREW_BUCKET_DUMMY
            || itemId == ItemID.BUCKET_WATER;
    }

    static boolean shouldShowSupplyBadge(
        boolean afkerMode,
        boolean waterBucket,
        boolean showWaterBucketCount,
        boolean showStationAmounts)
    {
        return afkerMode
            ? waterBucket && showWaterBucketCount
            : showStationAmounts;
    }

    private boolean isFlashOn()
    {
        return (System.currentTimeMillis() / FLASH_INTERVAL_MS) % 2L == 0L;
    }

    private boolean isEnabled(ResourceType resourceType, boolean emergencyWater)
    {
        return isCategoryEnabled(resourceType)
            && (!isFlashing(resourceType, emergencyWater) || isFlashOn());
    }

    private boolean isCategoryEnabled(ResourceType resourceType)
    {
        return plugin.isResourceHighlightEnabled(resourceType);
    }

    private boolean isFlashing(ResourceType resourceType, boolean emergencyWater)
    {
        if (emergencyWater)
        {
            return config.flashDamageRepair();
        }

        switch (resourceType)
        {
            case WATER:
                return config.flashWater();
            case COLOURED_WATER:
                return config.flashColouredWater();
            case HOPPERS:
                return config.flashHoppers();
            case BOILER_FUEL:
            case BOILER_EMPTY:
            case BOILER_UNLIT:
                return config.flashBoilerFuel();
            case BOILER_ACTIVE:
                return false;
            case BARK:
                return config.flashBark();
            case PROCESSED_BARK:
                return config.flashProcessedBark();
            case BAIT:
                return config.flashBait();
            case GRUBS:
                return config.flashGrubs();
            case FLOWERS:
                return config.flashFlowers();
            case BITTERNUTS:
                return config.flashBitternuts();
            case BITTERNUTS_FINAL:
                return config.flashBitternutsFinal();
            case ACTIVE_FIRE:
                return config.flashDamageRepair();
            case PIPE_REPAIR:
            case LUMBER_REPAIR:
            case DAMAGE_REPAIR:
                return config.flashDamageRepair()
                    && (plugin.getLocalTeamRepairParts(resourceType) > 0
                        || plugin.getLocalTeamObjectCount(resourceType) > 0);
            case CONVEYOR:
                return config.flashConveyor();
            case RUM:
                return config.flashRum();
            default:
                return false;
        }
    }

    private Color colourFor(ResourceType resourceType)
    {
        switch (resourceType)
        {
            case WATER:
                return config.waterColor();
            case COLOURED_WATER:
                return config.colouredWaterColor();
            case HOPPERS:
                return config.hopperColor();
            case BOILER_FUEL:
            case BOILER_EMPTY:
            case BOILER_UNLIT:
            case BOILER_ACTIVE:
                return config.boilerFuelColour();
            case BARK:
                return config.barkColor();
            case PROCESSED_BARK:
                return config.processedBarkColor();
            case BAIT:
                return config.baitColor();
            case GRUBS:
                return config.grubColor();
            case FLOWERS:
                return config.flowerColor();
            case BITTERNUTS:
                return config.bitternutColor();
            case BITTERNUTS_FINAL:
                return config.bitternutFinalColor();
            case PIPE_REPAIR:
                return config.waterColor();
            case LUMBER_REPAIR:
                return config.hopperColor();
            case ACTIVE_FIRE:
            case DAMAGE_REPAIR:
                return config.damageRepairColour();
            case CONVEYOR:
                return config.conveyorColor();
            case RUM:
                return config.rumColor();
            default:
                return Color.WHITE;
        }
    }

    private static Color withAlpha(Color colour, int alpha)
    {
        return new Color(colour.getRed(), colour.getGreen(), colour.getBlue(), alpha);
    }

    private static final class ItemOutlineKey
    {
        private final int itemId;
        private final int quantity;
        private final int colour;
        private final int size;

        private ItemOutlineKey(int itemId, int quantity, int colour, int size)
        {
            this.itemId = itemId;
            this.quantity = quantity;
            this.colour = colour;
            this.size = size;
        }

        @Override
        public boolean equals(Object object)
        {
            if (this == object)
            {
                return true;
            }
            if (!(object instanceof ItemOutlineKey))
            {
                return false;
            }

            ItemOutlineKey other = (ItemOutlineKey) object;
            return itemId == other.itemId
                && quantity == other.quantity
                && colour == other.colour
                && size == other.size;
        }

        @Override
        public int hashCode()
        {
            int result = itemId;
            result = 31 * result + quantity;
            result = 31 * result + colour;
            return 31 * result + size;
        }
    }
}

package com.tbhelper;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

import net.runelite.api.coords.WorldPoint;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.gameval.NpcID;
import net.runelite.api.gameval.ObjectID;
import org.junit.Test;

public class ObjectDatabaseTest
{
    @Test
    public void mapsDistinctBrewingStages()
    {
        assertEquals(
                ResourceType.FLOWERS,
                ObjectDatabase.getObject(ObjectID.BREW_FLOWER_KETTLE)
        );

        assertEquals(
                ResourceType.COLOURED_WATER,
                ObjectDatabase.getObject(ObjectID.BREW_COLOUR_WATER_RED_SIGN)
        );

        assertEquals(
                ResourceType.HOPPERS,
                ObjectDatabase.getObject(ObjectID.BREW_HOPPER_RED)
        );

        assertEquals(
                ResourceType.HOPPERS,
                ObjectDatabase.getObject(ObjectID.BREW_HOPPER_BLUE)
        );

        assertEquals(
                ResourceType.PROCESSED_BARK,
                ObjectDatabase.getObject(ObjectID.BREW_BARK_SIGN)
        );

        // Bottle machine is highlighted only while actively ejecting a bottle.
        assertEquals(
                ResourceType.RUM,
                ObjectDatabase.getObject(ObjectID.GAME_BREW_BOTTLE_MACHINE_SHAKE)
        );

        // Team conveyors are highlighted only while actively carrying rum.
        assertEquals(
                ResourceType.CONVEYOR,
                ObjectDatabase.getObject(ObjectID.BREW_RED_CONVEYOR_1)
        );

        assertEquals(
                ResourceType.CONVEYOR,
                ObjectDatabase.getObject(ObjectID.BREW_BLUE_CONVEYOR_1)
        );

        // Idle machinery is deliberately excluded.
        assertNull(
                ObjectDatabase.getObject(ObjectID.BREW_BOTTLE_MACHINE)
        );

        assertNull(
                ObjectDatabase.getObject(ObjectID.BREW_CONVEYER_BELT)
        );

        // Finished-rum collection crates share the neutral processing route.
        assertEquals(
                ResourceType.HOPPERS,
                ObjectDatabase.getObject(ObjectID.BREW_CRATE_RED)
        );

        assertEquals(
                ResourceType.HOPPERS,
                ObjectDatabase.getObject(ObjectID.BREW_CRATE_BLUE)
        );
    }

    @Test
    public void excludesDepletedSweetgrubMound()
    {
        assertEquals(ResourceType.BAIT, ObjectDatabase.getObject(ObjectID.BREW_SWEETGRUB_MOUND));
        assertNull(ObjectDatabase.getObject(ObjectID.BREW_SWEETGRUB_MOUND_DEPELETED));
    }

    @Test
    public void limitsSwarmSuppressionToTheNearbyMound()
    {
        WorldPoint mound = new WorldPoint(3200, 3200, 0);

        assertTrue(TroubleBrewingHighlighterPlugin.isSwarmNearMound(
            mound, new WorldPoint(3202, 3201, 0)));
        assertFalse(TroubleBrewingHighlighterPlugin.isSwarmNearMound(
            mound, new WorldPoint(3203, 3200, 0)));
        assertFalse(TroubleBrewingHighlighterPlugin.isSwarmNearMound(
            mound, new WorldPoint(3200, 3200, 1)));
    }

    @Test
    public void mapsInventoryStagesSeparately()
    {
        assertEquals(ResourceType.FLOWERS, ObjectDatabase.getItem(ItemID.BOWL_WATER));
        assertEquals(ResourceType.COLOURED_WATER, ObjectDatabase.getItem(ItemID.BREW_BOWL_RED));
        assertEquals(ResourceType.BAIT, ObjectDatabase.getItem(ItemID.RAW_RAT_MEAT));
        assertEquals(ResourceType.GRUBS, ObjectDatabase.getItem(ItemID.BREW_SWEETGRUBS));
        assertEquals(ResourceType.BARK, ObjectDatabase.getItem(ItemID.BREW_SCRAPEY_LOGS));
        assertEquals(ResourceType.BARK, ObjectDatabase.getItem(ItemID.BRONZE_AXE));
        assertEquals(ResourceType.BARK, ObjectDatabase.getItem(ItemID.KNIFE));
        assertEquals(ResourceType.PROCESSED_BARK,
            ObjectDatabase.getItem(ItemID.BREW_SCRAPEY_BARK));
        assertEquals(ResourceType.RUM, ObjectDatabase.getItem(ItemID.BREW_RED_RUM));
    }

    @Test
    public void mapsFireAndRepairStatesSeparately()
    {
        assertEquals(ResourceType.ACTIVE_FIRE,
            ObjectDatabase.getObject(ObjectID.BREW_PIPES_RED_BURNING_1));
        assertEquals(ResourceType.ACTIVE_FIRE,
            ObjectDatabase.getObject(ObjectID.BREW_HOPPER_BLUE_BURNING_2));
        assertEquals(ResourceType.ACTIVE_FIRE,
            ObjectDatabase.getObject(ObjectID.BREW_WATER_PUMP_FIRE));

        assertEquals(ResourceType.PIPE_REPAIR,
            ObjectDatabase.getObject(ObjectID.BREW_PIPES_RED_DAMAGED_1));
        assertEquals(ResourceType.PIPE_REPAIR,
            ObjectDatabase.getObject(ObjectID.BREW_PIPES_BLUE_WET_2));
        assertEquals(ResourceType.PIPE_REPAIR,
            ObjectDatabase.getObject(ObjectID.BREW_WATER_PUMP_DAMAGED));
        assertEquals(ResourceType.PIPE_REPAIR,
            ObjectDatabase.getItem(ItemID.BREW_PIPE_SECTION));

        assertEquals(ResourceType.LUMBER_REPAIR,
            ObjectDatabase.getObject(ObjectID.BREW_HOPPER_RED_DAMAGED_2));
        assertEquals(ResourceType.LUMBER_REPAIR,
            ObjectDatabase.getObject(ObjectID.BREW_HOPPER_BLUE_WET_1));
        assertEquals(ResourceType.LUMBER_REPAIR,
            ObjectDatabase.getItem(ItemID.BREW_LUMBER_PATCH));

        assertEquals(ResourceType.DAMAGE_REPAIR,
            ObjectDatabase.getObject(ObjectID.BREW_BRIDGE_RED_WET_1));
        assertEquals(ResourceType.DAMAGE_REPAIR,
            ObjectDatabase.getObject(ObjectID.BREW_BRIDGE_BLUE_WET_2));
        assertEquals(ResourceType.DAMAGE_REPAIR,
            ObjectDatabase.getItem(ItemID.BREW_BRIDGE_SECTION));
    }

    @Test
    public void interpretsRepairProgressAsPartsRemaining()
    {
        assertEquals(3, TroubleBrewingHighlighterOverlay.repairPartsRemaining(
            ObjectID.BREW_HOPPER_RED_DESTROYED));
        assertEquals(2, TroubleBrewingHighlighterOverlay.repairPartsRemaining(
            ObjectID.BREW_HOPPER_RED_DAMAGED_1));
        assertEquals(1, TroubleBrewingHighlighterOverlay.repairPartsRemaining(
            ObjectID.BREW_HOPPER_RED_DAMAGED_2));
        assertEquals(1, TroubleBrewingHighlighterOverlay.repairPartsRemaining(
            ObjectID.BREW_WATER_PUMP_DAMAGED));
        assertEquals(0, TroubleBrewingHighlighterOverlay.repairPartsRemaining(
            ObjectID.BREW_HOPPER_RED));
    }

    @Test
    public void mapsBoilerStatesSeparately()
    {
        assertEquals(ResourceType.BOILER_EMPTY,
            ObjectDatabase.getObject(ObjectID.BREW_STILL_BOILER));
        assertEquals(ResourceType.BOILER_EMPTY,
            ObjectDatabase.getObject(ObjectID.BREW_STILL_BOILER_CORNER_MIRROR));

        assertEquals(ResourceType.BOILER_UNLIT,
            ObjectDatabase.getObject(ObjectID.BREW_STILL_BOILER_LOGS));
        assertEquals(ResourceType.BOILER_UNLIT,
            ObjectDatabase.getObject(ObjectID.BREW_STILL_BOILER_CORNER_LOGS_MIRROR));

        assertEquals(ResourceType.BOILER_ACTIVE,
            ObjectDatabase.getObject(ObjectID.BREW_STILL_BOILER_FIRE));
        assertEquals(ResourceType.BOILER_ACTIVE,
            ObjectDatabase.getObject(ObjectID.BREW_STILL_BOILER_CORNER_FIRE_MIRROR));

        assertEquals(ResourceType.BOILER_FUEL,
            ObjectDatabase.getObject(ObjectID.BREW_LOG_STORE));
        assertEquals(ResourceType.BOILER_FUEL, ObjectDatabase.getItem(ItemID.LOGS));
        assertEquals(ResourceType.BOILER_FUEL, ObjectDatabase.getItem(ItemID.TINDERBOX));
    }

    @Test
    public void mapsPhysicalBoilersToTeamCounters()
    {
        assertEquals(2, TroubleBrewingHighlighterPlugin.getBoilerCounterIndex(
            ObjectID.BREW_STILL_BOILER_FIRE, false));
        assertEquals(1, TroubleBrewingHighlighterPlugin.getBoilerCounterIndex(
            ObjectID.BREW_STILL_BOILER_CORNER_FIRE, false));
        assertEquals(0, TroubleBrewingHighlighterPlugin.getBoilerCounterIndex(
            ObjectID.BREW_STILL_BOILER_CORNER_MIRROR, false));

        assertEquals(0, TroubleBrewingHighlighterPlugin.getBoilerCounterIndex(
            ObjectID.BREW_STILL_BOILER, true));
        assertEquals(1, TroubleBrewingHighlighterPlugin.getBoilerCounterIndex(
            ObjectID.BREW_STILL_BOILER_CORNER_LOGS, true));
        assertEquals(2, TroubleBrewingHighlighterPlugin.getBoilerCounterIndex(
            ObjectID.BREW_STILL_BOILER_CORNER_FIRE_MIRROR, true));
    }

    @Test
    public void calculatesRemainingRumCapacity()
    {
        assertEquals(29, TroubleBrewingHighlighterPlugin.remainingRums(0));
        assertEquals(22, TroubleBrewingHighlighterPlugin.remainingRums(7));
        assertEquals(0, TroubleBrewingHighlighterPlugin.remainingRums(29));
        assertEquals(0, TroubleBrewingHighlighterPlugin.remainingRums(30));
    }

    @Test
    public void clampsNativeContributionToRewardLimit()
    {
        assertEquals(0, TroubleBrewingHighlighterPlugin.clampContribution(-1));
        assertEquals(44, TroubleBrewingHighlighterPlugin.clampContribution(44));
        assertEquals(100, TroubleBrewingHighlighterPlugin.clampContribution(101));
    }

    @Test
    public void limitsRemainingRumToCyclesThatCanFinish()
    {
        assertPossibleRumsLeft(29, 0, 1200, -1);
        assertPossibleRumsLeft(29, 0, 1140, -1);
        assertPossibleRumsLeft(23, 0, 900, -1);
        assertPossibleRumsLeft(2, 0, 120, -1);
        assertPossibleRumsLeft(3, 0, 120, 10);
        assertPossibleRumsLeft(1, 0, 30, 10);
        assertPossibleRumsLeft(0, 0, 30, -1);
        assertPossibleRumsLeft(0, 0, 5, 0);
        assertPossibleRumsLeft(22, 7, 1200, -1);
        assertPossibleRumsLeft(29, 0, -1, -1);
    }

    @Test
    public void parsesNativeMatchTimerText()
    {
        assertEquals(900, TroubleBrewingHighlighterPlugin.parseMatchSeconds(
            "Time Left: 15 Mins"));
        assertEquals(125, TroubleBrewingHighlighterPlugin.parseMatchSeconds(
            "Time Left: 2:05"));
        assertEquals(-1, TroubleBrewingHighlighterPlugin.parseMatchSeconds("-"));
    }

    @Test
    public void recommendsTheLeastStockedRequiredIngredient()
    {
        assertEquals(
            "Fill sweetgrubs",
            TroubleBrewingHighlighterPlugin.lowestIngredientAction(
                6, 6, 2, 30, 18, 6)
        );
        assertEquals(
            "Fill water buckets",
            TroubleBrewingHighlighterPlugin.lowestIngredientAction(
                6, 4, 6, 5, 18, 6)
        );
        assertNull(TroubleBrewingHighlighterPlugin.lowestIngredientAction(
            6, 6, 6, 30, 18, 6));
        assertNull(TroubleBrewingHighlighterPlugin.lowestIngredientAction(
            0, 0, 0, 0, 0, 0));
    }

    private static void assertPossibleRumsLeft(
        int expected,
        int teamRumMade,
        int matchSecondsRemaining,
        int cycleSecondsRemaining)
    {
        assertEquals(
            expected,
            TroubleBrewingHighlighterPlugin.calculatePossibleRumsLeft(
                teamRumMade,
                matchSecondsRemaining,
                cycleSecondsRemaining
            )
        );
    }

    @Test
    public void mapsMonkeyAndBitternutStagesSeparately()
    {
        // Plain monkey NPC and inventory item match coloured water.
        assertEquals(
                ResourceType.COLOURED_WATER,
                ObjectDatabase.getNpc(NpcID.BREW_MONKEY)
        );
        assertEquals(
                ResourceType.COLOURED_WATER,
                ObjectDatabase.getItem(ItemID.BREW_MONKEY)
        );

        // Coloured monkey inventory items match the bitternut tree.
        assertEquals(
                ResourceType.BITTERNUTS,
                ObjectDatabase.getItem(ItemID.BREW_BLUE_MONKEY)
        );
        assertEquals(
                ResourceType.BITTERNUTS,
                ObjectDatabase.getItem(ItemID.BREW_RED_MONKEY)
        );
        assertEquals(
                ResourceType.BITTERNUTS,
                ObjectDatabase.getObject(ObjectID.BREW_BITTERNUT_TREE)
        );

        // Finished bitternut and its sign use their own final-stage group.
        assertEquals(
                ResourceType.BITTERNUTS_FINAL,
                ObjectDatabase.getItem(ItemID.BREW_BITTERNUT)
        );
        assertEquals(
                ResourceType.BITTERNUTS_FINAL,
                ObjectDatabase.getObject(ObjectID.BREW_BITTERNUT_SIGN)
        );
    }
}

package com.tbhelper;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import java.awt.Color;
import net.runelite.api.gameval.ObjectID;
import org.junit.Test;

public class TroubleBrewingHighlighterConfigTest
{
    private final TroubleBrewingHighlighterConfig config =
        new TroubleBrewingHighlighterConfig()
        {
        };

    @Test
    public void defaultsOnlyUrgentRoutesToFlashing()
    {
        assertTrue(config.flashDamageRepair());
        assertTrue(config.flashConveyor());

        assertFalse(config.flashWater());
        assertFalse(config.flashColouredWater());
        assertFalse(config.flashHoppers());
        assertFalse(config.flashBoilerFuel());
        assertFalse(config.flashBark());
        assertFalse(config.flashProcessedBark());
        assertFalse(config.flashBait());
        assertFalse(config.flashGrubs());
        assertFalse(config.flashFlowers());
        assertFalse(config.flashBitternuts());
        assertFalse(config.flashBitternutsFinal());
        assertFalse(config.flashRum());
    }

    @Test
    public void enablesPassiveHelpersByDefault()
    {
        assertTrue(config.showPiecesOfEight());
        assertTrue(config.showBrewStatus());
        assertTrue(config.showStationAmounts());
        assertTrue(config.showMonkeyDialogueHelper());
        assertTrue(config.preferJoinCrew());
    }

    @Test
    public void defaultsInventoryToItemOutlineAndAfkerModeOff()
    {
        assertEquals(InventoryHighlightStyle.ITEM_OUTLINE, config.inventoryHighlightStyle());
        assertEquals(2, config.inventoryOutlineSize());
        assertFalse(config.afkerMode());
        assertTrue(config.showAfkerInputHoppers());
        assertTrue(config.stopWaterHighlightsAt100());
        assertFalse(config.showWaterBucketCount());
    }

    @Test
    public void afkerInputHoppersExcludeRumCrates()
    {
        assertTrue(TroubleBrewingHighlighterPlugin.isAfkerInputHopper(
            ObjectID.BREW_HOPPER_RED));
        assertTrue(TroubleBrewingHighlighterPlugin.isAfkerInputHopper(
            ObjectID.BREW_HOPPER_BLUE));
        assertFalse(TroubleBrewingHighlighterPlugin.isAfkerInputHopper(
            ObjectID.BREW_CRATE_RED));
        assertFalse(TroubleBrewingHighlighterPlugin.isAfkerInputHopper(
            ObjectID.BREW_CRATE_BLUE));
    }

    @Test
    public void afkerWaterStopsAtContributionCapUnlessFireIsActive()
    {
        assertTrue(TroubleBrewingHighlighterPlugin.shouldShowAfkerWater(true, 99, false));
        assertFalse(TroubleBrewingHighlighterPlugin.shouldShowAfkerWater(true, 100, false));
        assertTrue(TroubleBrewingHighlighterPlugin.shouldShowAfkerWater(true, 100, true));
        assertTrue(TroubleBrewingHighlighterPlugin.shouldShowAfkerWater(false, 100, false));
    }

    @Test
    public void bucketCountToggleOnlyOverridesNormalBadgesInAfkerMode()
    {
        assertTrue(TroubleBrewingInventoryOverlay.shouldShowSupplyBadge(
            false, true, false, true));
        assertFalse(TroubleBrewingInventoryOverlay.shouldShowSupplyBadge(
            true, true, false, true));
        assertTrue(TroubleBrewingInventoryOverlay.shouldShowSupplyBadge(
            true, true, true, true));
        assertFalse(TroubleBrewingInventoryOverlay.shouldShowSupplyBadge(
            true, false, true, true));
    }

    @Test
    public void defaultsActiveConveyorsToOrange()
    {
        assertEquals(new Color(255, 108, 0), config.conveyorColor());
    }

    @Test
    public void defaultsMonkeyDialogueToBitternutRouteColour()
    {
        assertEquals(config.bitternutColor(), config.monkeyDialogueColor());
    }
}

